INSERT INTO glossary_terms (id, term, slug, definition, status) VALUES
('glo-aaron-sumo-sacerdote', 'Aarón (sumo sacerdote)', 'aaron-sumo-sacerdote', 'Aarón fue hermano de Moisés, levita y colaborador suyo durante el éxodo. En la narrativa bíblica fue consagrado para ejercer el sacerdocio y aparece como el primer sumo sacerdote de Israel, con funciones representativas y cultuales vinculadas al tabernáculo.', 'Publicado básico'),
('glo-abdias-mayordomo-acab', 'Abdías (mayordomo de Acab)', 'abdias-mayordomo-acab', 'Abdías fue el funcionario encargado de la casa o palacio del rey Acab. El relato destaca que temía profundamente a Jehová y que, durante la persecución promovida por Jezabel, escondió a cien profetas de Jehová en cuevas y los sostuvo con pan y agua. Más tarde, durante la gran sequía, encontró a Elías y llevó a Acab el aviso de que el profeta estaba presente.', 'Publicado básico'),
('glo-abdias-profeta-libro', 'Abdías (profeta del libro de Abdías)', 'abdias-profeta-libro', 'Abdías es el profeta identificado por nombre en la apertura del libro que lleva su nombre, una breve profecía dirigida principalmente contra Edom. El texto condena la violencia y la complacencia de Edom ante la calamidad de Jerusalén y anuncia juicio sobre Edom, restauración para Sion y el dominio final de YHWH.', 'Publicado básico'),
('glo-abel', 'Abel', 'abel', 'Abel fue hijo de Adán y Eva y hermano de Caín. Génesis lo presenta como pastor de ovejas, cuya ofrenda de los primogénitos de su rebaño fue mirada con agrado por Dios; posteriormente fue asesinado por su hermano Caín. El Nuevo Testamento lo recuerda como “justo” y como ejemplo de fe.', 'Publicado básico'),
('glo-abiam-abias-rey-juda', 'Abiam / Abías (rey de Judá; hijo de Roboam)', 'abiam-abias-rey-juda', 'Abiam/Abías fue hijo y sucesor de Roboam y el segundo rey de Judá después de la división del reino. Reinó tres años en Jerusalén; 1 Reyes evalúa negativamente su fidelidad religiosa, mientras que 2 Crónicas destaca su confrontación con Jeroboam, su discurso en el monte Zemaraim y la victoria de Judá. Su hijo Asa lo sucedió en el trono.', 'Publicado básico'),
('glo-abimelec-hijo-gedeon', 'Abimelec (hijo de Gedeón/Jerobaal)', 'abimelec-hijo-gedeon', 'Abimelec fue hijo de Gedeón/Jerobaal y de una concubina de Siquem. Tras la muerte de Gedeón obtuvo el apoyo de los líderes de Siquem, hizo matar a sus hermanos —con excepción de Jotam— y fue proclamado rey. El relato lo presenta gobernando tres años antes de que se rompiera su alianza con Siquem; después destruyó la ciudad y murió durante el ataque a Tebes, cuando una mujer dejó caer sobre su cabeza una piedra superior de molino y él pidió a su escudero que lo rematara con la espada. Su historia funciona como una crítica severa al poder obtenido mediante violencia y traición.', 'Publicado básico'),
('glo-abisag-sunamita', 'Abisag sunamita', 'abisag-sunamita', 'Abisag fue una joven sunamita escogida en los últimos días del rey David para atenderlo y ayudar a darle calor. El texto la describe como muy hermosa, señala expresamente que David no tuvo relaciones sexuales con ella y la presenta después en el trasfondo de la sucesión: Adonías pidió casarse con Abisag, petición que Salomón interpretó como ligada a una pretensión al reino.', 'Publicado básico'),
('glo-absalon-hijo-david', 'Absalón (hijo de David)', 'absalon-hijo-david', 'Absalón fue hijo del rey David y de Maaca, hija de Talmai, rey de Gesur. La narrativa de 2 Samuel lo presenta como un príncipe israelita de notable apariencia, hermano de Tamar, vengador de la agresión de Amnón y, más tarde, líder de una rebelión contra David que terminó con su muerte. 2 Samuel destaca de manera excepcional su belleza física y la abundancia de su cabello.', 'Publicado básico'),
('glo-acab-rey-israel', 'Acab (rey de Israel)', 'acab-rey-israel', 'Acab fue hijo y sucesor de Omri, esposo de Jezabel y rey de Israel con capital en Samaria durante veintidós años. 1 Reyes lo presenta en conflicto repetido con el profeta Elías, involucrado en guerras con Aram y responsable, junto con Jezabel, del caso de la viña de Nabot; murió después de ser herido en batalla en Ramot de Galaad.', 'Publicado básico'),
('glo-acaz-rey-juda', 'Acaz (rey de Judá)', 'acaz-rey-juda', 'Acaz fue hijo de Jotam, rey de Judá, y reinó en Jerusalén durante dieciséis años. Su gobierno estuvo marcado por la guerra siro-efraimita, su recurso a Tiglat-pileser III de Asiria y profundas alteraciones religiosas en Judá.', 'Publicado básico'),
('glo-adan', 'Adán', 'adan', 'Adán es presentado en Génesis como el primer hombre: Dios lo forma del polvo de la tierra, le da aliento de vida, lo coloca en Edén y le da a Eva como esposa. Después de su desobediencia, ambos son expulsados del jardín; Adán aparece luego como padre de Caín, Abel, Set y otros hijos e hijas. En el Nuevo Testamento, Pablo lo identifica como el primer hombre y lo contrasta con Cristo en su exposición sobre pecado, muerte y vida.', 'Publicado básico'),
('glo-adonias-hijo-david', 'Adonías (hijo de David y Haguit)', 'adonias-hijo-david', 'Hijo de David y Haguit y uno de los hijos nacidos en Hebrón. Cuando David envejeció, Adonías intentó adelantarse en la sucesión proclamando su aspiración al trono, organizó una exhibición propia de un pretendiente real y obtuvo el apoyo de Joab y del sacerdote Abiatar; David, sin embargo, hizo reconocer a Salomón como rey. Después, Adonías pidió a Abisag sunamita por esposa, solicitud que Salomón interpretó como una nueva pretensión dinástica y que terminó con la muerte de Adonías.', 'Publicado básico'),
('glo-agar', 'Agar', 'agar', 'Agar es presentada en Génesis como la sierva egipcia de Sarai. Ante la falta de hijos de Sarai, fue dada a Abram para que concibiera por medio de ella; Agar dio a luz a Ismael. Más adelante, ella e Ismael fueron enviados fuera de la casa de Abraham, y el relato describe la provisión de Dios para ambos en el desierto. Génesis la identifica explícitamente como egipcia y como mujer en condición servil dentro de la casa de Sarai.', 'Publicado básico'),
('glo-ahias-silonita-profeta', 'Ahías silonita (profeta)', 'ahias-silonita-profeta', 'Profeta de Silo activo en la transición entre el reinado de Salomón y el surgimiento del reino del norte. Anunció a Jeroboam que recibiría diez tribus mediante el signo de romper una vestidura nueva en doce partes; más tarde, ya anciano, comunicó juicio contra la casa de Jeroboam. 1 Reyes 12:15 presenta la división del reino como cumplimiento de la palabra dada por medio de Ahías.', 'Publicado básico'),
('glo-ahitofel-gilonita', 'Ahitofel gilonita', 'ahitofel-gilonita', 'Consejero de David procedente de Gilo que, durante la rebelión de Absalón, abandonó al rey y pasó a asesorar al hijo rebelde. El relato destaca la extraordinaria autoridad que tenía su consejo; cuando Absalón prefirió la estrategia de Husai y su propio plan fue desechado, Ahitofel regresó a su ciudad, puso en orden su casa y se quitó la vida.', 'Publicado básico'),
('glo-aholiab-artesano-del-tabernaculo', 'Aholiab (artesano del tabernáculo)', 'aholiab-artesano-del-tabernaculo', 'Hijo de Ahisamac, de la tribu de Dan, Aholiab fue designado junto con Bezaleel para la obra artesanal del tabernáculo. El texto lo presenta con capacidad para enseñar y lo vincula con trabajos de artífice, diseñador y recamador en azul, púrpura, carmesí y lino fino.', 'Publicado básico'),
('glo-aman-hijo-hamedata', 'Amán (hijo de Hamedata; agagueo)', 'aman-hijo-hamedata', 'Alto funcionario de Asuero en el libro de Ester. Después de ser elevado sobre los demás príncipes, reaccionó contra Mardoqueo por negarse a inclinarse ante él y promovió un decreto para destruir a los judíos del imperio; Ester finalmente expuso su plan ante el rey, y Amán murió en la misma estructura que había preparado para Mardoqueo.', 'Publicado básico'),
('glo-amasias-rey-juda', 'Amasías (rey de Judá)', 'amasias-rey-juda', 'Hijo y sucesor del rey Joás de Judá. Amasías subió al trono a los 25 años y reinó 29 años en Jerusalén; consolidó su autoridad castigando a los asesinos de su padre sin ejecutar a sus hijos, derrotó a Edom y posteriormente desafió a Joás de Israel, fue vencido en Bet-semes y capturado, y años después murió en una conspiración tras huir a Laquis.', 'Publicado básico'),
('glo-amasias-sacerdote-betel-amos7', 'Amasías (sacerdote de Bet-el; Amós 7)', 'amasias-sacerdote-betel-amos7', 'Amasías fue el sacerdote de Bet-el que denunció ante Jeroboam II la predicación de Amós y luego ordenó al profeta que abandonara Bet-el. El propio relato vincula su función sacerdotal con un santuario estrechamente asociado a la monarquía del reino de Israel.', 'Publicado básico'),
('glo-amnon-hijo-david', 'Amnón (hijo de David)', 'amnon-hijo-david', 'Amnón fue el primogénito de David, nacido en Hebrón de Ahinoam jezreelita. En 2 Samuel 13 engañó a Tamar, su media hermana, para dejarla sola con él y la violó; dos años después, Absalón ordenó matarlo durante una celebración en Baal-hazor como venganza por lo sucedido.', 'Publicado básico'),
('glo-amos-profeta-tecoa', 'Amós (profeta de Tecoa)', 'amos-profeta-tecoa', 'Profeta originario de Tecoa, en Judá, activo durante los reinados de Uzías de Judá y Jeroboam II de Israel. El propio libro lo presenta ligado al cuidado de ganado y de sicómoros antes de ser llamado a profetizar a Israel; su confrontación con Amasías en Bet-el deja claro que su autoridad profética no dependía de una profesión o gremio profético, sino del llamado recibido.', 'Publicado básico'),
('glo-ana-madre-samuel', 'Ana (madre de Samuel)', 'ana-madre-samuel', 'Esposa de Elcana y madre del profeta Samuel. En Silo, Ana oró con profunda aflicción y formuló un voto respecto del hijo que pedía; después del nacimiento y destete de Samuel, lo llevó al santuario para dedicarlo al servicio de Dios. Su relato continúa con un cántico de alabanza y con sus visitas anuales, en las que llevaba a Samuel una pequeña túnica hecha por ella.', 'Publicado básico'),
('glo-ana-profetisa-hija-fanuel', 'Ana (profetisa; hija de Fanuel)', 'ana-profetisa-hija-fanuel', 'Profetisa anciana, hija de Fanuel y de la tribu de Aser, que aparece en el Templo de Jerusalén durante la presentación de Jesús. Lucas la describe dedicada al servicio de Dios con ayunos y oraciones; al encontrarse con el niño, dio gracias a Dios y habló de él a quienes esperaban la redención de Jerusalén.', 'Publicado básico'),
('glo-andres-apostol', 'Andrés (apóstol; hermano de Pedro)', 'andres-apostol', 'Discípulo de Jesús, hermano de Simón Pedro y uno de los Doce. Los Evangelios lo presentan como pescador del mar de Galilea; en Juan aparece primero siguiendo a Jesús y llevando a su hermano Simón ante él, después señalando al muchacho que tenía cinco panes de cebada y dos peces, y más tarde acompañando a Felipe cuando unos griegos quisieron acercarse a Jesús.', 'Publicado básico');
